import { cn } from '@/registry/ndeko/lib/utils';

import type { Pillar } from './data';

type LeaderStyle = React.CSSProperties & { '--row': string };

const SPINE_DELAY_MS = 150;

const BRANCH_DELAY_MS = 380;

const BRANCH_STEP_MS = 90;

const LEADERS_STYLE: LeaderStyle = { '--row': '2.75rem' };

function delayOf(milliseconds: number) {
  return { transitionDelay: `${milliseconds}ms` };
}

function branchDelayOf(index: number) {
  return delayOf(BRANCH_DELAY_MS + index * BRANCH_STEP_MS);
}

function labelDelayOf(index: number) {
  return delayOf(BRANCH_DELAY_MS + 200 + index * BRANCH_STEP_MS);
}

type LeadersProps = {
  pillar: Pillar;
};

/** The lines draw from the hexagon each time the pillar changes, because the keyed wrapper mounts again. */
export function Leaders({ pillar }: LeadersProps) {
  return (
    <div
      key={pillar.id}
      style={LEADERS_STYLE}
      className='relative [--spine:50%] @3xl:[--spine:2rem]'
    >
      <span
        aria-hidden='true'
        style={delayOf(0)}
        className={cn(
          'bg-foreground/60 absolute hidden h-px w-(--spine) origin-left transition-transform duration-300 ease-(--ease-out-strong) @3xl:top-1/2 @3xl:left-0 @3xl:block starting:scale-x-0'
        )}
      />
      <span
        aria-hidden='true'
        style={delayOf(0)}
        className='bg-foreground/60 absolute top-0 left-(--spine) h-[calc(var(--row)/2)] w-px origin-top transition-transform duration-200 ease-(--ease-out-strong) @3xl:hidden starting:scale-y-0'
      />
      <span
        aria-hidden='true'
        style={delayOf(SPINE_DELAY_MS)}
        className='bg-foreground/60 absolute top-[calc(var(--row)/2)] bottom-[calc(var(--row)/2)] left-(--spine) w-px origin-top transition-transform duration-[350ms] ease-(--ease-out-strong) starting:scale-y-0'
      />
      <ul className='flex flex-col'>
        {pillar.capabilities.map((capability, index) => (
          <li
            key={capability}
            className='relative flex h-(--row) items-center ps-[calc(var(--spine)+1.75rem)]'
          >
            <span
              aria-hidden='true'
              style={branchDelayOf(index)}
              className='bg-foreground/60 absolute left-(--spine) h-px w-6 origin-left transition-transform duration-200 ease-(--ease-out-strong) starting:scale-x-0'
            />
            <span
              style={labelDelayOf(index)}
              className='text-sm font-medium transition-[opacity,translate] duration-300 ease-(--ease-out-strong) @2xl:text-base starting:translate-x-1 starting:opacity-0'
            >
              {capability}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { MenuIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import {
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/registry/ndeko/ui/collapsible';

import { HEADER, type NavLink } from './data';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const ICON_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW =
  'flex h-10 items-center rounded-md px-2 text-sm text-foreground outline-none transition-colors hover:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25';

function iconVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ICON_VARIANTS;
}

function toggleGlyphOf(isOpen: boolean) {
  if (isOpen) {
    return { key: 'close', icon: <XIcon /> };
  }
  return { key: 'open', icon: <MenuIcon /> };
}

function toggleLabelOf(isOpen: boolean) {
  if (isOpen) {
    return 'Close menu';
  }
  return 'Open menu';
}

export function MobileMenuTrigger({ isOpen }: { isOpen: boolean }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const iconVariants = iconVariantsOf(shouldReduceMotion);
  const glyph = toggleGlyphOf(isOpen);

  return (
    <CollapsibleTrigger
      render={
        <Button
          variant='ghost'
          size='icon'
          className='@3xl:hidden'
          aria-label={toggleLabelOf(isOpen)}
        />
      }
    >
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={glyph.key}
          className='flex'
          variants={iconVariants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {glyph.icon}
        </motion.span>
      </AnimatePresence>
    </CollapsibleTrigger>
  );
}

type NavigateHandler = (event: React.MouseEvent<HTMLAnchorElement>) => void;

type MobileMenuPanelProps = {
  links: NavLink[];
  onNavigate: NavigateHandler;
};

export function MobileMenuPanel({ links, onNavigate }: MobileMenuPanelProps) {
  return (
    <CollapsibleContent className='@3xl:hidden'>
      <nav aria-label='Main' className='flex flex-col gap-4 pt-2 pb-5'>
        <ul className='flex flex-col'>
          {links.map((link) => (
            <li key={link.id}>
              <a href={link.href} className={ROW} onClick={onNavigate}>
                {link.label}
              </a>
            </li>
          ))}
        </ul>
        <div className='px-2'>
          <Button
            size='lg'
            className='w-full'
            nativeButton={false}
            render={<a href={HEADER.actionHref} onClick={onNavigate} />}
          >
            {HEADER.action}
          </Button>
        </div>
      </nav>
    </CollapsibleContent>
  );
}

'use client';

import { useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { SettleItem } from '@/registry/ndeko/ui/settle';

import { PILLARS, PILLARS_ANCHOR, PILLARS_SECTION } from './data';
import { Leaders } from './leaders';
import { Plate } from './plate';
import { turnedTo } from './plate-geometry';
import { Reveal } from './reveal';

const TOUR_INDEXES = [1, 2, 3, 4, 5, 0];

const TOUR_STEP_MS = 3400;

const KEY_STEPS: Record<string, 1 | -1> = {
  ArrowRight: 1,
  ArrowDown: 1,
  ArrowLeft: -1,
  ArrowUp: -1,
};

export function Pillars() {
  const [activeIndex, setActiveIndex] = useState(0);
  const [turn, setTurn] = useState(0);
  const pillar = PILLARS[activeIndex];

  function pick(index: number) {
    setActiveIndex(index);
    setTurn((current) => turnedTo(current, index));
  }

  const tourSteps = TOUR_INDEXES.map((index) => ({
    after: TOUR_STEP_MS,
    run: () => pick(index),
  }));
  const { ref, isAutoplaying } = useAutoplay(tourSteps, {
    loopAfter: TOUR_STEP_MS,
  });
  const announcement = `${pillar.name}: ${pillar.capabilities.join(', ')}`;
  const message = spokenUnless(isAutoplaying, announcement);

  function moveWithKeys(event: React.KeyboardEvent<HTMLDivElement>) {
    const step = KEY_STEPS[event.key];
    if (!step) {
      return;
    }
    event.preventDefault();
    const next = (activeIndex + step + PILLARS.length) % PILLARS.length;
    const group = event.currentTarget;
    pick(next);
    requestAnimationFrame(() => {
      const selector = `[data-pillar="${PILLARS[next].id}"]`;
      group.querySelector<HTMLElement>(selector)?.focus();
    });
  }

  return (
    <section
      id={PILLARS_ANCHOR}
      className='px-4 py-16 @sm:px-6 @sm:py-24 @5xl:px-8'
    >
      <Reveal
        className='mx-auto max-w-6xl'
        groupClassName='grid gap-12 @3xl:grid-cols-[minmax(0,1fr)_minmax(0,1.7fr)] @3xl:items-center @3xl:gap-12'
      >
        <SettleItem className='flex flex-col gap-8'>
          <div className='flex flex-col gap-3'>
            <h2 className='text-3xl font-semibold text-balance @2xl:text-4xl'>
              {PILLARS_SECTION.title}
            </h2>
            <p className='text-muted-foreground text-base text-pretty'>
              {PILLARS_SECTION.description}
            </p>
          </div>
          <div className='flex flex-col gap-1'>
            <p className='text-muted-foreground text-xs tabular-nums'>
              {pillar.number}
            </p>
            <p className='text-3xl font-semibold'>
              <Swap swapKey={pillar.id}>{pillar.name}</Swap>
            </p>
            <p className='text-muted-foreground text-[13px]'>{pillar.line}</p>
          </div>
        </SettleItem>
        <SettleItem>
          <div
            ref={ref}
            className='grid @3xl:grid-cols-[minmax(0,1fr)_minmax(0,0.95fr)] @3xl:items-center'
          >
            <div className='mx-auto w-full max-w-[19rem] @3xl:max-w-none'>
              <Plate
                activeIndex={activeIndex}
                turn={turn}
                onPick={pick}
